def area_page(a):
    body = sec("", '<div class="prose">%s</div>' % a["intro"])
    body += sec("Τι προσέχουμε εδώ", steps(a["points"]), cls="sec sec-tint")
    body += sec("Ποια πισίνα ταιριάζει", cards(a["types"]), narrow=False)
    if a.get("gallery"):
        body += sec("Από τα έργα μας", gallery(a["gallery"]), cls="sec sec-tint", narrow=False)
    body += sec("Πού κατασκευάζουμε", '<ul class="chips">%s</ul>' % "".join("<li>%s</li>" % x for x in a["places"])
                + note(PRICE + '<p>Δείτε και τις <a href="/perioxes/">υπόλοιπες περιοχές</a>.</p>'))
    return P("el", "/perioxes/%s/" % a["slug"], a["title"] + " | Πισίνα Προκάτ Ελλάδα", a["desc"], a["h1"], a["lead"],
             a["hero"], a["hero_alt"], body, short=a["short"], kicker=a["region"], crumbs=AREAS_CRUMB, faq=a["faq"])


def pages():
    return [area_page(a) for a in AREAS]
